"""Embed the editable web pages as UTF-8 C strings; no network or dependencies."""
from pathlib import Path
import json

root = Path(__file__).resolve().parent
lines = ['/* Generated by embed_web.py; edit the HTML files in web instead. */', '#pragma once']
for name, filename in [('HTML_CONFIG', 'config.html'), ('HTML_OVERLAY', 'overlay.html'), ('HTML_SHIFTER', 'shifter.html')]:
    html = (root / 'web' / filename).read_text(encoding='utf-8')
    lines.append(f'static const char {name}[] =')
    # Chunk by source line to keep generated files inspectable.
    chunks = html.splitlines(keepends=True) or ['']
    for chunk in chunks:
        lines.append(json.dumps(chunk, ensure_ascii=False))
    lines[-1] += ';'
output = root / 'web_ui.h'
text = '\n'.join(lines) + '\n'
if not output.exists() or output.read_text(encoding='utf-8') != text:
    output.write_text(text, encoding='utf-8', newline='\n')

